SELECT 'датчик «holder-stub» ' || fact_gap($1, 'holder-stub') || ': настоящий ли держатель — неизвестно, а не «настоящий»' AS detail WHERE NOT fact_fresh($1, 'holder-stub') UNION ALL SELECT f.name || '  —  ' || f.detail AS detail FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'holder-stub' AND true ORDER BY 1
